--
-- Name: match_memories(public.vector, double precision, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_memories(query_embedding public.vector, similarity_threshold double precision DEFAULT 0.7, match_count integer DEFAULT 20, filter_source text DEFAULT NULL::text, filter_type text DEFAULT NULL::text) RETURNS TABLE(id integer, content text, type text, source text, similarity double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        me.id,
        me.content,
        me.type,
        me.source,
        (1 - (me.embedding <=> query_embedding))::FLOAT AS similarity
    FROM memory_entries me
    WHERE (filter_source IS NULL OR me.source = filter_source)
      AND (filter_type   IS NULL OR me.type   = filter_type)
      AND me.embedding IS NOT NULL
      AND (1 - (me.embedding <=> query_embedding)) >= similarity_threshold
    ORDER BY me.embedding <=> query_embedding
    LIMIT match_count;
END;
$$;


