CREATE TABLE public.fips199_categorizations (
    id integer NOT NULL,
    project_id text NOT NULL,
    categorization_date text DEFAULT now(),
    categorizer text DEFAULT 'icdev-compliance-engine'::text,
    confidentiality_impact text NOT NULL,
    integrity_impact text NOT NULL,
    availability_impact text NOT NULL,
    overall_categorization text NOT NULL,
    categorization_method text DEFAULT 'information_type'::text,
