    CONSTRAINT fips199_categorizations_categorization_method_check CHECK ((categorization_method = ANY (ARRAY['information_type'::text, 'manual'::text, 'inherited'::text, 'cnssi_1253'::text]))),
    CONSTRAINT fips199_categorizations_confidentiality_impact_check CHECK ((confidentiality_impact = ANY (ARRAY['Low'::text, 'Moderate'::text, 'High'::text]))),
    CONSTRAINT fips199_categorizations_integrity_impact_check CHECK ((integrity_impact = ANY (ARRAY['Low'::text, 'Moderate'::text, 'High'::text]))),
    CONSTRAINT fips199_categorizations_overall_categorization_check CHECK ((overall_categorization = ANY (ARRAY['Low'::text, 'Moderate'::text, 'High'::text]))),
    CONSTRAINT fips199_categorizations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'approved'::text, 'superseded'::text])))
);


