--
-- Name: govlift_workloads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.govlift_workloads (
    id text NOT NULL,
    name text NOT NULL,
    workload_type text NOT NULL,
    os_name text DEFAULT ''::text,
    os_version text DEFAULT ''::text,
    environment text DEFAULT 'production'::text,
    ip_address text DEFAULT ''::text,
    cpu_cores integer DEFAULT 4,
    memory_gb real DEFAULT 8.0,
    storage_tb real DEFAULT 1.0,
    classification text DEFAULT 'CUI'::text,
    risk_level text DEFAULT 'medium'::text,
    migration_status text DEFAULT 'discovered'::text,
    wave_id text,
    last_scanned text,
    notes text DEFAULT ''::text,
    created_at text DEFAULT now(),
    updated_at text DEFAULT now(),
    map_score integer DEFAULT 0,
    dim_business integer DEFAULT 0,
    dim_operational integer DEFAULT 0,
    dim_platform integer DEFAULT 0,
    dim_security integer DEFAULT 0,
    dim_people integer DEFAULT 0,
    dim_process integer DEFAULT 0,
    dim_data integer DEFAULT 0,
    business_value integer DEFAULT 3,
    technical_debt integer DEFAULT 3,
    dependency_count integer DEFAULT 0,
    assessed_at text,
    auto_assessed integer DEFAULT 0,
    map_strategy text DEFAULT ''::text,
    CONSTRAINT govlift_workloads_map_strategy_check CHECK ((map_strategy = ANY (ARRAY[''::text, 'rehost'::text, 'replatform'::text, 'refactor'::text, 'repurchase'::text, 'retain'::text, 'retire'::text]))),
    CONSTRAINT govlift_workloads_migration_status_check CHECK ((migration_status = ANY (ARRAY['discovered'::text, 'assessed'::text, 'wave_assigned'::text, 'in_migration'::text, 'migrated'::text, 'failed'::text, 'rollback'::text]))),
    CONSTRAINT govlift_workloads_risk_level_check CHECK ((risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT govlift_workloads_workload_type_check CHECK ((workload_type = ANY (ARRAY['web_app'::text, 'database'::text, 'api_service'::text, 'batch_job'::text, 'message_queue'::text, 'storage'::text, 'network_appliance'::text, 'legacy_app'::text])))
);


