CREATE TABLE IF NOT EXISTS public.dm_catalog_entries (
    id              TEXT PRIMARY KEY,
    product_id      TEXT REFERENCES public.dm_data_products(id) ON DELETE CASCADE,
    catalog_name    TEXT NOT NULL,
